const token = $json.token;
const locs = $('Locations').all();
const ymd = (d) => { const p = Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(d).filter(x => x.type !== 'literal').map(x => [x.type, x.value])); return p.year + '-' + p.month + '-' + p.day; };
const tomorrow = ymd(new Date(Date.now() + 86400000));
const dayAfter = ymd(new Date(Date.now() + 2 * 86400000));
return locs.map(l => ({ json: {
  token, location: l.json.location, location_id: l.json.location_id, from_number: l.json.from_number, target_date: tomorrow,
  url: 'https://nexhealth.info/appointments?' + new URLSearchParams({ subdomain: $env.NEXHEALTH_SUBDOMAIN || '', location_id: String(l.json.location_id), start: tomorrow + 'T00:00:00', end: dayAfter + 'T00:00:00', timezone: TZ, cancelled: 'false', per_page: '500' }).toString(),
} }));

