// ---- end helpers ----

// Phone numbers stay inside this execution (7-day n8n retention); only hashes reach Postgres.
const appts = $('Flatten appointments').all();
const out = [];
$input.all().forEach((item, i) => {
  const a = appts[i] ? appts[i].json : null;
  if (!a || item.json.error) return;
  const d = item.json.data || {};
  const p = d.patient || d.user || d;
  const bio = p.bio || {};
  const phone = e164(bio.cell_phone_number || bio.phone_number || bio.home_phone_number || null);
  if (!phone) return;
  const when = new Date(a.start_time);
  out.push({ json: {
    location: a.location, from_number: a.from_number, appointment_id: a.appointment_id,
    patient_ref: patientRef(a.patient_id), phone, phone_hash: sha256(phone + SALT), phone_last4: phone.slice(-4),
    day: fmt(when, { weekday: 'long', month: 'long', day: 'numeric' }), time: fmt(when, { hour: 'numeric', minute: '2-digit' }),
    provider: providerFirst(a.provider_id, a.provider_name) || '',
  } });
});
return out;

// Hard limits: skip suppressed numbers, max 1 reminder contact per patient per day, max 3 per week.
const contacts = $('Prepare contacts').all();
const out = [];
$input.all().forEach((row, i) => {
  const c = contacts[i] ? contacts[i].json : null;
  if (!c) return;
  const r = row.json;
  if (r.suppressed) return;
  if (Number(r.contacts_day) >= 1) return;
  if (Number(r.contacts_week) >= 3) return;
  out.push({ json: Object.assign({}, c, { channel: r.sms_opt_in ? 'sms' : 'voice' }) });
});
return out;

// One batch call per location number. call_time_window uses minutes since local midnight (default 10:00 to 18:00).
const groups = {};
for (const it of $input.all()) {
  const c = it.json;
  if (!c.from_number) continue;
  (groups[c.from_number] = groups[c.from_number] || { from_number: c.from_number, location: c.location, contacts: [] }).contacts.push(c);
}
const TZ = $env.PRACTICE_TZ || 'America/New_York';
const startMin = Number($env.REMINDER_CALL_WINDOW_START_MIN || 600);
const endMin = Number($env.REMINDER_CALL_WINDOW_END_MIN || 1080);
return Object.values(groups).map(g => ({ json: {
  location: g.location, from_number: g.from_number, contacts: g.contacts,
  batch_body: {
    name: 'reminders-' + g.location + '-' + new Date().toISOString().slice(0, 10),
    from_number: g.from_number,
    reserved_concurrency: 2,
    call_time_window: { windows: [{ start: startMin, end: endMin }], timezone: TZ },
    tasks: g.contacts.map(c => ({
      to_number: c.phone,
      override_agent_id: $env.RETELL_REMINDER_AGENT_ID || undefined,
      metadata: { appointment_ref: c.appointment_id },
      retell_llm_dynamic_variables: { practice_name: String($env.PRACTICE_NAME || ''), location: c.location, day: c.day, time: c.time, provider: c.provider, callback: c.from_number },
    })),
  },
} }));

const groups = $('Group voice reminders by location').all();
const out = [];
$input.all().forEach((res, i) => {
  const g = groups[i] ? groups[i].json : null;
  if (!g) return;
  const ok = !res.json.error;
  for (const c of g.contacts) out.push({ json: { patient_ref: c.patient_ref, appointment_id: c.appointment_id, location: c.location, batch_call_id: ok ? (res.json.batch_call_id || null) : null, outcome: ok ? 'ok' : 'error' } });
});
return out;
